  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'DEV-HOUR', qty: 10, name: 'Development (hour)', unitPrice: 1000, vatRate: 21, discountPercent: 150 }],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 10000);
  assert.equal(totals.discount, 15000);
  assert.equal(totals.total, 0);
});

test('addLine with discountPercent stores the discount', () => {
  const result1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const result2 = addLine(result1.value, { sku: 'STICKER', qty: 50, discountPercent: 15 });
  assert.equal(result2.ok, true);
  assert.equal(result2.value.lines[1].discountPercent, 15);
});

test('addLine without discountPercent defaults to 0', () => {
  const result1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const result2 = addLine(result1.value, { sku: 'STICKER', qty: 50 });
  assert.equal(result2.ok, true);
  assert.equal(result2.value.lines[1].discountPercent, 0);
});

test('addLine rejects invalid discountPercent', () => {
  const result1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.deepEqual(addLine(result1.value, { sku: 'STICKER', qty: 50, discountPercent: -10 }), { ok: false, error: 'DISCOUNT_INVALID' });
  assert.deepEqual(addLine(result1.value, { sku: 'STICKER', qty: 50, discountPercent: 105 }), { ok: false, error: 'DISCOUNT_INVALID' });
  assert.deepEqual(addLine(result1.value, { sku: 'STICKER', qty: 50, discountPercent: 'fifty' }), { ok: false, error: 'DISCOUNT_INVALID' });
});

test('addLine updates discountPercent when SKU already exists', () => {
  const result1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5, discountPercent: 10 }],
  });

  const result2 = addLine(result1.value, { sku: 'DEV-HOUR', qty: 3, discountPercent: 20 });
  assert.equal(result2.ok, true);
  assert.equal(result2.value.lines[0].qty, 8);
  assert.equal(result2.value.lines[0].discountPercent, 20);
});

