import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, lineDiscount, invoiceTotals, addLine, removeLine, issueInvoice } from '../src/invoices.js';

test('createInvoice creates an invoice with product details filled in', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }, { sku: 'STICKER', qty: 100 }],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-001');
  assert.equal(result.value.issueDate, '2026-10-07');
  assert.equal(result.value.status, 'draft');
  assert.equal(result.value.lines.length, 2);

  assert.equal(result.value.lines[0].sku, 'DEV-HOUR');
  assert.equal(result.value.lines[0].name, 'Development (hour)');
  assert.equal(result.value.lines[0].qty, 10);
  assert.equal(result.value.lines[0].unitPrice, 9500);
  assert.equal(result.value.lines[0].vatRate, 21);

  assert.equal(result.value.lines[1].sku, 'STICKER');
  assert.equal(result.value.lines[1].name, 'Sticker sheet');
  assert.equal(result.value.lines[1].qty, 100);
  assert.equal(result.value.lines[1].unitPrice, 50);
  assert.equal(result.value.lines[1].vatRate, 21);
});

test('createInvoice rejects an unknown customer', () => {
  const result = createInvoice({
    customerId: 'C-999',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.deepEqual(result, { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('createInvoice rejects an invalid date format', () => {
  assert.deepEqual(createInvoice({
    customerId: 'C-001',
    issueDate: '10/07/2026',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  }), { ok: false, error: 'DATE_INVALID' });

  assert.deepEqual(createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-7',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  }), { ok: false, error: 'DATE_INVALID' });

  assert.deepEqual(createInvoice({
    customerId: 'C-001',
    issueDate: 'not-a-date',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  }), { ok: false, error: 'DATE_INVALID' });
});

test('createInvoice rejects an impossible date', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2000-02-30',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.deepEqual(result, { ok: false, error: 'DATE_INVALID' });
});

test('createInvoice rejects an empty lines array', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [],
  });

  assert.deepEqual(result, { ok: false, error: 'NO_LINES' });
});

test('createInvoice rejects invalid quantities', () => {
  // Zero quantity
  assert.deepEqual(createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 0 }],
  }), { ok: false, error: 'QTY_INVALID' });

  // Negative quantity
  assert.deepEqual(createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: -5 }],
  }), { ok: false, error: 'QTY_INVALID' });

  // Float quantity
  assert.deepEqual(createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1.5 }],
  }), { ok: false, error: 'QTY_INVALID' });

  // Non-numeric quantity
  assert.deepEqual(createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 'ten' }],
  }), { ok: false, error: 'QTY_INVALID' });
});

test('createInvoice rejects an unknown SKU', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'UNKNOWN-SKU', qty: 1 }],
  });

  assert.deepEqual(result, { ok: false, error: 'UNKNOWN_SKU' });
});

test('createInvoice does not mutate the input', () => {
  const lines = [{ sku: 'DEV-HOUR', qty: 10 }];
  const originalLines = JSON.parse(JSON.stringify(lines));

  createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines,
  });

  assert.deepEqual(lines, originalLines);
});

test('lineTotal calculates qty × unitPrice', () => {
  assert.equal(lineTotal({ qty: 10, unitPrice: 9500 }), 95000);
  assert.equal(lineTotal({ qty: 100, unitPrice: 50 }), 5000);
  assert.equal(lineTotal({ qty: 1, unitPrice: 245000 }), 245000);
});

test('invoiceTotals sums line totals and sets total equal to subtotal', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }, { sku: 'STICKER', qty: 100 }],
  });

  const totals = invoiceTotals(result.value);
  assert.equal(totals.subtotal, 95000 + 5000);
  assert.equal(totals.total, 100000);
});

test('invoiceTotals with a single line', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 2 }],
  });

  const totals = invoiceTotals(result.value);
  assert.equal(totals.subtotal, 120000 * 2);
  assert.equal(totals.total, 240000);
});

test('invoiceTotals with multiple varied lines', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'COPY-HOUR', qty: 3 },
      { sku: 'STICKER', qty: 250 },
    ],
  });

  const totals = invoiceTotals(result.value);
  const expected = (9500 * 5) + (6000 * 3) + (50 * 250);
  assert.equal(totals.subtotal, expected);
  assert.equal(totals.total, expected);
});

test('addLine adds a new line to an invoice', () => {
  const result1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const result2 = addLine(result1.value, { sku: 'STICKER', qty: 50 });
  assert.equal(result2.ok, true);
  assert.equal(result2.value.lines.length, 2);
  assert.equal(result2.value.lines[1].sku, 'STICKER');
  assert.equal(result2.value.lines[1].qty, 50);
});

test('addLine updates qty if SKU already exists on invoice', () => {
  const result1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const result2 = addLine(result1.value, { sku: 'DEV-HOUR', qty: 3 });
  assert.equal(result2.ok, true);
  assert.equal(result2.value.lines.length, 1);
  assert.equal(result2.value.lines[0].qty, 8);
});

test('addLine validates quantity', () => {
  const result1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.deepEqual(addLine(result1.value, { sku: 'STICKER', qty: 0 }), { ok: false, error: 'QTY_INVALID' });
  assert.deepEqual(addLine(result1.value, { sku: 'STICKER', qty: -5 }), { ok: false, error: 'QTY_INVALID' });
  assert.deepEqual(addLine(result1.value, { sku: 'STICKER', qty: 1.5 }), { ok: false, error: 'QTY_INVALID' });
});

test('addLine validates SKU', () => {
  const result1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.deepEqual(addLine(result1.value, { sku: 'UNKNOWN-SKU', qty: 1 }), { ok: false, error: 'UNKNOWN_SKU' });
});

test('addLine refuses to modify non-draft invoices', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'sent',
    lines: [{ sku: 'DEV-HOUR', qty: 5, name: 'Development (hour)', unitPrice: 9500, vatRate: 21 }],
  };

  assert.deepEqual(addLine(invoice, { sku: 'STICKER', qty: 1 }), { ok: false, error: 'NOT_DRAFT' });
});

test('addLine does not mutate the input', () => {
  const result1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const originalLines = JSON.parse(JSON.stringify(result1.value.lines));
  addLine(result1.value, { sku: 'STICKER', qty: 50 });
  assert.deepEqual(result1.value.lines, originalLines);
});

test('removeLine removes a line from an invoice', () => {
  const result1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'STICKER', qty: 50 },
    ],
  });

  const result2 = removeLine(result1.value, 'STICKER');
  assert.equal(result2.ok, true);
  assert.equal(result2.value.lines.length, 1);
  assert.equal(result2.value.lines[0].sku, 'DEV-HOUR');
});

test('removeLine rejects if SKU not on invoice', () => {
  const result1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.deepEqual(removeLine(result1.value, 'UNKNOWN-SKU'), { ok: false, error: 'LINE_NOT_FOUND' });
});

test('removeLine rejects if it would leave no lines', () => {
  const result1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.deepEqual(removeLine(result1.value, 'DEV-HOUR'), { ok: false, error: 'NO_LINES' });
});

test('removeLine refuses to modify non-draft invoices', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
