  const result1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const result2 = addLine(result1.value, { sku: 'STICKER', qty: 50, discountPercent: 0 });
  assert.equal(result2.ok, true);
  assert.equal(result2.value.lines[1].discountPercent, 0);
});

